import z3,itertools,math,pickle,time

def test(groups,target,timeout=120000):
 ix=list(itertools.product(*[range(n+1) for n in groups]));vs={x:z3.Bool('v_'+ '_'.join(map(str,x))) for x in ix}
 s=z3.Solver();s.set(timeout=timeout)
 for x in ix:
  if sum(x)<=7:continue
  terms=[vs[y] for y in ix if all((b&a)==b for a,b in zip(x,y))]
  e=terms[0]
  for t in terms[1:]:e=z3.Xor(e,t)
  s.add(z3.Not(e))
 weights={x:math.prod(math.comb(n,k) for n,k in zip(groups,x)) for x in ix}
 s.add(z3.PbEq([(vs[x],weights[x]) for x in ix],target))
 t=time.time();r=s.check();print(groups,target,r,round(time.time()-t,2),flush=True)
 if r==z3.sat:
  support=[x for x in ix if z3.is_true(s.model().eval(vs[x]))]
  pickle.dump((groups,target,support),open('symmetric_witness_'+str(target)+'.pkl','wb'));print(support,flush=True)
 return r
