import numpy as np,math
from scipy.optimize import linprog
for n in [322,326,330,334]:
 low={0,64,96,112,120,124,126,128,136,144,148}
 allowed={x for x in range(n+1) if x%2==0 and (x in low or x>=152)}
 allowed={x for x in allowed if n-x in allowed}
 ix=sorted(x for x in allowed if 0<x<=n//2)
 # A_x=A_n-x variables
 K=np.empty((n+1,n+1));K[0,:]=1;K[1,:]=1-2*np.arange(n+1)/n
 for j in range(1,n):K[j+1,:]=((n-2*np.arange(n+1))*K[j,:]-j*K[j-1,:])/(n-j)
 # normalized K_j / binomial(n,j)
 for k in [15,16]:
  scale=2**k
  mat=np.array([[2*K[j,x] for x in ix] for j in range(0,n+1,2)])
  b=np.array([-2*K[j,0] for j in range(0,n+1,2)])
  # inequalities K sum>=0 plus selforthog B_i>=A_i
  for row,j in enumerate(range(0,n+1,2)):
   if j in ix:mat[row,ix.index(j)]-=scale/math.comb(n,j)
   elif n-j in ix:mat[row,ix.index(n-j)]-=scale/math.comb(n,j)
  eq=np.array([[2.0]*len(ix),[2*K[2,x] for x in ix]])
  rhs=np.array([scale-2,-2*K[2,0]])
  r=linprog(np.zeros(len(ix)),A_ub=-mat,b_ub=-b,A_eq=eq,b_eq=rhs,bounds=(0,None),method='highs')
  print(n,k,r.message)
